import { unstable_cache } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

// In-memory store standing in for a real database.
const posts: Post[] = []

export async function insertPost(data: Pick<Post, 'title' | 'content'>) {
  const post: Post = {
    id: crypto.randomUUID(),
    title: data.title,
    content: data.content,
    createdAt: new Date().toISOString(),
  }
  posts.unshift(post)
  return post
}

export const getPosts = unstable_cache(async () => [...posts], ['posts'], {
  tags: ['posts'],
})

