'use server'

import { updateTag } from 'next/cache'
import { insertPost } from '@/lib/posts'

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title || !content) {
    throw new Error('Title and content are required')
  }

  await insertPost({ title, content })

  // updateTag expires the "posts" tag immediately (read-your-own-writes), so
  // the next render blocks on fresh data instead of serving stale content.
  // revalidateTag(tag, 'max') would serve stale data while revalidating.
  updateTag('posts')
}

